L000391	\section{Monotonicity}\label{sup_mono}
L000392	
L000393	
L000394	A pure state entanglement monotone is defined as a local unitary invariant function which is concave under any local operation \cite{Gadde:2024jfi}
L000395	
L000396	\begin{align}\label{mono1}
L000397		f(|\psi\rangle_{\textrm{\tiny{ABC}}}) \geq \sum_i p_i f\left(\left|\psi_i\right\rangle_{\textrm{\tiny{ABC}}}\right)
L000398	\end{align}
L000399	 $|\psi_i\rangle_{\textrm{\tiny{ABC}}}$ in the above equation denotes the states obtained  post a one party local operation such that the state $\rho=\ket{\psi}\bra{\psi}$ is converted into $\Lambda(\rho)$ as follows
L000400	\begin{align}\label{Lam}
L000401		\Lambda(\rho)=\sum_i p_i|\psi_i \rangle\langle\psi_i|, \quad p_i:=|| E_i^{(A) }\ket{\psi}||^ 2, \quad \ket{\psi_i}:=E_i^{(A)}|\psi\rangle / \sqrt{p_i}
L000402	\end{align}
L000403	 $E_i^{A}$ correspond to a trace preserving operation on subsystem $A$
L000404	\begin{align}
L000405	 \sum_i E_i^{\dagger (A)} E_i^{(A)}=\mathbb{I}
L000406	\end{align}
L000407	
L000408	
L000409	Consider the state \(\ket{\phi}\), which serves as a purification of the reduced density matrix \(\rho_{\textrm{\tiny{AB}}}\). This reduced density matrix is obtained by tracing out subsystem \(C\) from the original state \(\ket{\psi}\). Likewise, we define \(\ket{\phi_i}\) as the purification of the reduced density matrix \(\rho_{i,\textrm{\tiny{AB}}} = \mathrm{Tr}_C(\ket{\psi_i})\). The state \(\ket{\phi}\) resides in the Hilbert space \(\mathcal{H}_{AB} \otimes \mathcal{H}_{\tilde{A}}\), where the auxiliary space \(\mathcal{H}_{\tilde{A}}\) must be at least as large in dimension as the rank of \(\rho_{\textrm{\tiny{AB}}}\).  Since all possible purifications of the bipartite system—including the original state \(\ket{\psi}\)—are connected via such transformations and the function \(f\) is a local unitary invariant,  it follows that \(f\) takes the same value for any of these purifications.
L000410	
L000411	\begin{align}
L000412	    f(\ket{\phi})=f(\ket{\psi}),\quad  f(\ket{\phi_i})=f(\ket{\psi_i})
L000413	\end{align}
L000414	Therefore,  \cref{mono1} may equally well be expressed through the canonically purifications as follows
L000415	\begin{align}
L000416		f(\ket{\phi}) \geq \sum_i p_i f(\ket{\phi_i})
L000417	\end{align}
L000418	We can now utilize the above result in the context of our measure which  is obtained through the canonical purification, where \(\ket{\phi}\) resides in the Hilbert space \(\mathcal{H}_{AB} \otimes \mathcal{H}_{A^*B^*}\). Here, the auxiliary Hilbert space \(\mathcal{H}_{A^*B^*}\) has a dimension exactly equal to the rank of the reduced density matrix \(\rho_{\textrm{\tiny{AB}}}\).
L000419	In the context of canonical purification, our next step is to demonstrate that
L000420	
L000421	\begin{align}
L000422		f(\ket{\sqrt{\rho_{\textrm{\tiny{AB}}}}}) \geq \sum_i p_i  f(\ket{\sqrt{\rho_{\textrm{i,\tiny{AB}}}}})
L000423	\end{align}
L000424	In the above equation \(\ket{\sqrt{\rho_{\textrm{\tiny{AB}}}}}\) and \(\ket{\sqrt{\rho_{\textrm{i,\tiny{AB}}}}}\) correspond to the canonical purifications of the reduced density matrices \(\rho_{\textrm{\tiny{AB}}}\) and \(\rho_{i,\textrm{\tiny{AB}}}\), respectively.
L000425	Observe that the action of the map \(\Lambda\) on \(\rho\) in \cref{Lam} can equivalently be interpreted as the effect of the map \(\tilde{\Lambda}\) on the canonically purified state \(\ket{\sqrt{\rho_{\textrm{\tiny{AB}}}}}\). This transformation results in the states \(\ket{\sqrt{\rho_{\textrm{i,\tiny{AB}}}}}\) with probabilities
L000426	
L000427	\begin{align}
L000428		\tilde{\Lambda}( \ket{\sqrt{\rho_{\textrm{\tiny{AB}}}}})=\sum_i p_i \ket{\sqrt{\rho_{\textrm{i,\tiny{AB}}}}}\bra{\sqrt{\rho_{\textrm{i,\tiny{AB}}}}}.
L000429	\end{align}
L000430	We now aim to show that \(\tilde{\Lambda}\) corresponds simply to a local operation \(\Lambda\) acting on \(A\) and its reflected counterpart \(A^*\). To illustrate this, let us examine the reduced density matrix \(\rho_{i,\textrm{\tiny{AB}}}\) that results from applying a local operation \(E_i\) on \(A\) alone.
L000431	\begin{align}\label{rhoi}
L000432		\rho_{i,AB}&=Tr_{C}(\rho_{\psi_i})\notag\\
L000433		&=\frac{E_i^{(A)}Tr_C(\rho_{\psi})E_i^{\dagger(A)}}{p_i}\\
L000434		&=\frac{E_i^{(A)}\rho_{AB}E_i^{\dagger(A)}}{p_i}
L000435	\end{align}
L000436	Since \(E_i^{(A)}\) acts only on subsystem \(A\), we can interchange the order of the operation and the trace over \(C\) in the second line.  Next, we express the reduced density matrix \(\rho_{\textrm{\tiny{AB}}}\) as a sum of pure states:
L000437	\begin{align}\label{redexp}
L000438		\rho_{AB}=\sum_i q_i \ket{\lambda_i}\bra{\lambda_i}
L000439	\end{align}
L000440	The corresponding canonical purification is given by
L000441	\begin{align}
L000442		\ket{\sqrt{\rho_{\textrm{\tiny{AB}}}}}=\sum_i \sqrt{q_i} \ket{\lambda_i}\ket{\lambda_i}
L000443	\end{align}
L000444	We may now utilize \cref{rhoi} and \cref{redexp} to obtain
L000445	\begin{align}
L000446		\rho_{i,AB}=\sum_j q_j \frac{E_i^{(A)}}{\sqrt{p_i}}\ket{\lambda_j}\bra{\lambda_j}\frac{E_i^{\dagger(A)}}{\sqrt{p_i}}
L000447	\end{align}
L000448	The corresponding canonical purification therefore is given by
L000449	\begin{align}
L000450		\ket{\sqrt{\rho_{i,\textrm{\tiny{AB}}}}}&=\sum_j \sqrt{q_j} \frac{E^{(A)}_i\otimes E^{(A^*)}_i}{p_i}\ket{\lambda_j}\ket{\lambda_j}\notag\\
L000451		\ket{\sqrt{\rho_{i,\textrm{\tiny{AB}}}}}& =\frac{E^{(A)}_i}{\sqrt{p_i}}\otimes \frac{E^{(A^*)}_i}{\sqrt{p_i}}\ket{\sqrt{\rho_{\textrm{\tiny{AB}}}}}&
L000452	\end{align}
L000453	This conclusively shows that a local operation on \(A\) in the original state induces a corresponding local operation on both \(A\) and its reflected counterpart \(A^*\) in the canonically purified states.  Having established this, our next step is to demonstrate that the \(L\)-entropy satisfies the monotonicity property under local operations on \(A\) and \(A^*\). To do so, we invoke a well-known result from quantum information theory: the mutual information is non-increasing under local quantum operations, a property commonly referred to as the \textit{data processing inequality}.
L000454	
L000455	\begin{align}
L000456		I(A:A^*)_{\ket{\sqrt{\rho_{\textrm{i,\tiny{AB}}}}}} \leq I(A:A^*)_{\sqrt{\rho_{AB}} }\nonumber\\
L000457		I(B:B^*)_{\ket{\sqrt{\rho_{\textrm{i,\tiny{AB}}}}}} \leq I(B:B^*)_{\sqrt{\rho_{AB}} }
L000458	\end{align}
L000459	This further implies that
L000460	\begin{align}
L000461		Min[ I(A:A^*),I(B:B^*)]_{\ket{\sqrt{\rho_{\textrm{i,\tiny{AB}}}}}}\leq Min[I(A:A^*),I(B:B^*)]_{\sqrt{\rho_{AB}}}\nonumber\\
L000462	\end{align}
L000463	Therefore, we obtain the following result
L000464	\begin{align}
L000465		\ell_{AB}\geq \sum_i p_i \ell_{i,AB}\nonumber\\
L000466	\end{align}
L000467	where \(\ell_{\textrm{\tiny{AB}}}\) and \(\ell_{\textrm{i,\tiny{AB}}}\) denote the \(L\)-entropies associated with the canonically purified states \(\ket{\sqrt{\rho_{\textrm{\tiny{AB}}}}}\) and \(\ket{\sqrt{\rho_{\textrm{i,\tiny{AB}}}}}\), respectively.  Notice that in the proof above, we analyzed monotonicity with respect to a local operation on \(A\). The same reasoning applies to local operations on \(B\), while a local operation on \(C\) leaves \(\ell_{\textrm{\tiny{AB}}}\) unchanged.
L000468	Therefore, we have established the proof that \(\ell_{\textrm{\tiny{AB}}}\) is a pure-state entanglement monotone.
