L000499	\section{Generalized L-entropy}\label{gen_L}
L000500	In this section, we define the generalized latent entropy, $L_{\text{gen}}$, as a hierarchical refinement of the $L$-entropy presented in \cite{newlentropy} mentioned in the main article. For a given $n$-party pure state, the generalized L-entropy can be constructed utilizing the following steps.
L000501	
L000502	\begin{enumerate}
L000503		\item For an $n$-party pure state $\rho_{A_1\cdots A_n}$, construct all reduced density matrices $\rho_k$ with $2\leq k\leq \text{Max}\left[2,\lfloor n/2 \rfloor\right]$.
L000504		\item Canonically purify each $\rho_k$ as $\rho_{A_1\cdots A_k} \;\longrightarrow\; \ket{\sqrt{\rho_{A_1\cdots A_k}}}_{A_1\cdots A_k A_1^*\cdots A_k^*}$.
L000505		\item Compute the reflected entropy $S_R(\mathcal{A}:\mathcal{B})$ by bipartitioning the $k$ parties into two complementary subsets: $\mathcal{A}=A_1A_2\cdot\cdot\cdot A_{\lfloor \frac{k}{2}\rfloor}$ containing $\lfloor k/2\rfloor$ parties and $\mathcal{B}=A_{\lfloor \frac{k}{2}\rfloor+1}A_{\lfloor \frac{k}{2}\rfloor+2}\cdot\cdot\cdot A_{k}$ containing the rest. It is possible to choose $\mathcal{A}$ and $\mathcal{B}$ in $n_k$ different ways where $n_k$ is given as,
L000506		$$
L000507		n_k =
L000508		\begin{cases}
L000509			\dfrac{1}{2}\binom{k}{k/2}, & k \ \text{even}, \\[6pt]
L000510			\binom{k}{\lfloor k/2\rfloor}, & k \ \text{odd}.
L000511		\end{cases}
L000512		$$
L000513		\item Utilizing the upper bound of the reflected entropy, define $\ell_k^{(i)}$ as,
L000514		\begin{align}\label{genell}
L000515			\ell_k^{(i)} = 2 \min\{S(\mathcal{A}), S(\mathcal{B})\} - S_R(\mathcal{A}:\mathcal{B}),
L000516		\end{align}
L000517		where $i$ denotes a particular combination of $\mathcal{A}$ and $\mathcal{B}$ among $n_k$ different ways.
L000518		\item For fixed $k$, consider the geometric mean of all $\ell_k^{(i)}$s
L000519		\[
L000520		L_k = \Big(\prod_{i=1}^{n_k} \ell_k^{(i)}\Big)^{1/n_k}.
L000521		\]
L000522		\item Finally, the generalized latent entropy is defined as
L000523		\[
L000524		L_{\text{gen}}(A_1\cdots A_n) = \Big(\prod_{k=2}^{\lfloor n/2 \rfloor} L_k\Big)^{1/\lfloor n/2 \rfloor}.
L000525		\]
L000526	\end{enumerate}
L000527	Note that, this generalized construction can also be used for $n\leq5$ party systems which exactly results to the formulation explained in main article. It can be easily shown that the generalized L-entropy satisfies all the conditions to qualify as a GME measure. Interestingly, the generalized L-entropy provides a hierarchy of $k$-uniform states according to amount of GME present \cite{newlentropy}. In this context, the $\lfloor\frac{n}{2}\rfloor$-uniform states, known as absolutely maximally entangled (AME) states, yield the presence of maximum possible GME in $n$-party pure states.
